(()=>{'use strict';if(!document.body.classList.contains('shared-app'))return;let from='',to='',memberId='';const previous=renderReports;renderReports=function(){previous();if(!management())return;const root=el('#sharedContent'),presence=el('#presenceReport');if(presence)presence.remove();const included=t=>{const d=t.due||(t.created_at||'').slice(0,10);return(!from||d>=from)&&(!to||d<=to)},filtered=tasks.filter(included),people=members.filter(m=>m.active&&(!memberId||m.id===memberId));const total=filtered.filter(t=>!memberId||t.owner_id===memberId),count=s=>total.filter(t=>t.status===s).length;root.innerHTML='<h2>گزارش وضعیت افراد</h2><form id="peopleRange" class="range-controls"><label>از تاریخ<input type="date" name="from" aria-label="شروع بازه گزارش" value="'+from+'"></label><label>تا تاریخ<input type="date" name="to" aria-label="پایان بازه گزارش" value="'+to+'"></label><label>عضو پروژه<select name="member"><option value="">همه اعضا</option>'+members.filter(m=>m.active).map(m=>'<option value="'+esc(m.id)+'" '+(memberId===m.id?'selected':'')+'>'+esc(m.name)+'</option>').join('')+'</select></label><button class="primary">اعمال بازه</button><button type="button" id="clearPeopleRange" class="secondary">همه زمان‌ها</button></form><p class="shared-meta">مبنای بازه: مهلت کار؛ برای کار بدون مهلت، تاریخ تعریف. آمار زیر مربوط به مسئول اصلی است. درصد تکمیل، معیار قطعی بازدهی فرد نیست.</p><div class="people-kpis">'+[['کل کارها',total.length],['در دست انجام',count('open')],['منتظر تأیید',count('review')],['تأییدشده',count('done')]].map(([l,n])=>'<div><span>'+l+'</span><b>'+fa(n)+'</b></div>').join('')+'</div><div class="report-legend"><span class="open">در دست انجام</span><span class="review">منتظر تأیید</span><span class="done">تأییدشده</span></div><section class="people-charts">'+people.map(m=>{const own=filtered.filter(t=>t.owner_id===m.id),counts=['open','review','done'].map(s=>own.filter(t=>t.status===s).length),n=own.length,percent=n?Math.round(counts[2]/n*100):null;return '<article class="person-chart"><div><b>'+esc(m.name)+'</b><strong>'+(percent===null?'—':fa(percent)+'٪ تکمیل')+'</strong></div><div class="person-stack" role="img" aria-label="'+esc(m.name)+': '+counts.map((n,i)=>labels[['open','review','done'][i]]+' '+fa(n)).join('، ')+'">'+counts.map((c,i)=>c?'<span class="'+['open','review','done'][i]+'" style="width:'+c/Math.max(1,n)*100+'%" title="'+labels[['open','review','done'][i]]+': '+fa(c)+'">'+fa(c)+'</span>':'').join('')+'</div><p>'+fa(n)+' کار · '+fa(counts[0])+' در دست انجام · '+fa(counts[1])+' منتظر تأیید · '+fa(counts[2])+' تأییدشده</p></article>'}).join('')+'</section>';if(presence)root.append(presence);el('#peopleRange').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),a=f.get('from'),b=f.get('to');if(a&&b&&a>b)return message('تاریخ شروع باید قبل از پایان باشد.');from=a;to=b;memberId=f.get('member');renderReports()};el('#clearPeopleRange').onclick=()=>{from=to=memberId='';renderReports()}}})();
